INSERT INTO lesson_authoring (lesson_id,video_id,source_start_ms,source_end_ms,revision,transcript_revision,approved_revision,karaoke_reviewed_revision,semantic_revision,timing_status,active_job_id,document,published_at,source_selected_at,timing_evidence,generation_options,audio_source_id,tts_voice,content_profile,auto_continue,published_by)
SELECT snapshot.*
FROM seed_lesson_authoring snapshot
JOIN seed_lesson_inserted inserted ON inserted.id = snapshot.lesson_id;

-- Materialize the same rows as JdbcAuthoringRepository.publish before locking the snapshots.
CREATE TEMP TABLE seed_lesson_sentence ON COMMIT DROP AS
SELECT authoring.lesson_id, (sentence.value->>'id')::uuid AS id,
       (sentence.ordinality - 1)::integer AS position, sentence.value AS content
FROM lesson_authoring authoring
JOIN seed_lesson_inserted inserted ON inserted.id = authoring.lesson_id
CROSS JOIN LATERAL jsonb_array_elements(authoring.document) WITH ORDINALITY sentence(value, ordinality);

INSERT INTO lesson_sentence (id,lesson_id,position,text,audio_start_ms,audio_end_ms)
SELECT id,lesson_id,position,content->>'text',
       (content->'words'->0->>'startMs')::bigint,
       (content->'words'->(-1)->>'endMs')::bigint
FROM seed_lesson_sentence;

INSERT INTO lesson_word_timestamp (id,sentence_id,position,surface_text,start_ms,end_ms)
SELECT gen_random_uuid(),sentence.id,(word.ordinality - 1)::integer,word.value->>'text',
       (word.value->>'startMs')::bigint,(word.value->>'endMs')::bigint
FROM seed_lesson_sentence sentence
CROSS JOIN LATERAL jsonb_array_elements(sentence.content->'words') WITH ORDINALITY word(value, ordinality);

INSERT INTO sentence_pronunciation (id,sentence_id,accent,ipa,provider,model,text_hash)
SELECT gen_random_uuid(),sentence.id,COALESCE(sentence.content->>'ipaAccent',authoring.generation_options->>'accent'),
       sentence.content->>'ipa','LOCAL',sentence.content->>'ipaVersion',
       encode(sha256(convert_to(sentence.content->>'text','UTF8')),'hex')
FROM seed_lesson_sentence sentence
JOIN lesson_authoring authoring ON authoring.lesson_id = sentence.lesson_id
WHERE NULLIF(btrim(sentence.content->>'ipa'),'') IS NOT NULL;

INSERT INTO lesson_annotation (id,lesson_id,sentence_id,annotation_type,payload_json)
SELECT gen_random_uuid(),lesson_id,id,'CONTENT',content
FROM seed_lesson_sentence;

INSERT INTO lesson_activity (id,lesson_id,activity_type,position,config_json)
SELECT gen_random_uuid(),authoring.lesson_id,activity.type,activity.position,
       jsonb_build_object('options',authoring.generation_options,'profile',authoring.content_profile,'clozeVersion','cloze-v2')
FROM lesson_authoring authoring
JOIN seed_lesson_inserted inserted ON inserted.id = authoring.lesson_id
CROSS JOIN (VALUES ('WATCH',0),('DICTATION',1),('SHADOWING',2)) activity(type,position)
WHERE activity.type = 'WATCH' OR (authoring.generation_options->'activities') ? activity.type;

INSERT INTO lesson_activity_sentence (activity_id,sentence_id)
SELECT activity.id,sentence.id
FROM lesson_activity activity
JOIN seed_lesson_sentence sentence ON sentence.lesson_id = activity.lesson_id
WHERE activity.activity_type = 'WATCH'
   OR (activity.activity_type = 'DICTATION' AND (sentence.content->>'dictationSelected')::boolean)
   OR (activity.activity_type = 'SHADOWING' AND (sentence.content->>'shadowingSelected')::boolean);

INSERT INTO lesson_category_membership (lesson_id,category_id)
SELECT inserted.id,category.id
FROM (VALUES
    ('246d7560-e4a3-4807-a022-190220c7a00d','20000000-0000-0000-0000-000000000001'),
    ('2cfe1fcd-017c-4512-b071-e981c0945632','20000000-0000-0000-0000-000000000017'),
    ('de2cc719-0f15-4f25-b845-5504fcdf1860','20000000-0000-0000-0000-000000000018'),
    ('bc3b286b-10c6-47fd-b4d4-4c3c30ff4edc','20000000-0000-0000-0000-000000000018'),
    ('c9f2b0da-c8a2-4636-8a14-8a1667957259','20000000-0000-0000-0000-000000000024'),
    ('6f6e6cf8-7c1f-4d0a-9f8d-2c14d95d5b01','20000000-0000-0000-0000-000000000013'),
    ('7dca3d68-9c75-4e8c-8f59-5af5fbd34a02','20000000-0000-0000-0000-000000000013')
) snapshot (lesson_id,category_id)
JOIN seed_lesson_inserted inserted ON inserted.id = snapshot.lesson_id::uuid
JOIN lesson_category category ON category.id = snapshot.category_id::uuid;

UPDATE lesson_authoring authoring
SET published_at = lesson.updated_at
FROM lesson
JOIN seed_lesson_inserted inserted ON inserted.id = lesson.id
WHERE authoring.lesson_id = inserted.id;

-- Additional locally authored lesson snapshots.

-- Active drafts keep their status. Learner accounts, progress, job logs and secrets are excluded.

CREATE TEMP TABLE seed_extra_lesson (id uuid PRIMARY KEY) ON COMMIT DROP;

