INSERT INTO lesson_sentence SELECT snapshot.* FROM jsonb_populate_recordset(NULL::lesson_sentence, '[{"id":"008021bd-5aae-48ec-9b20-5bd9fea68775","text":"When I saw you in that dress, looking so beautiful","position":41,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":202749,"audio_start_ms":196798,"audio_clip_object_key":null},{"id":"0096146d-ddec-45d1-9cff-e5be47c2ba1a","text":"Where the skies are blue","position":24,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":75246,"audio_start_ms":73608,"audio_clip_object_key":null},{"id":"00f95f25-565a-4d79-8869-2baae4ef994b","text":"Where the fields are green","position":28,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":88835,"audio_start_ms":86955,"audio_clip_object_key":null},{"id":"01276423-f5f6-4961-a9ce-8ba47a9b20e8","text":"I''m all alone, the rooms are getting smaller","position":14,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":37969,"audio_start_ms":34295,"audio_clip_object_key":null},{"id":"01f14a9e-0280-40af-a55c-92d15b950b72","text":"So, I say a little prayer","position":53,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":190569,"audio_start_ms":189307,"audio_clip_object_key":null},{"id":"023d324f-17ef-4752-94ca-11e1fd322f65","text":"I''m a bit jealous because the countryside is a fantastic place to relax,","position":7,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":16960,"audio_start_ms":11840,"audio_clip_object_key":null},{"id":"058181bf-6922-4afc-ad78-eec1dc45a624","text":"Listening to our favourite song","position":49,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":242138,"audio_start_ms":238756,"audio_clip_object_key":null},{"id":"066c4347-9b56-4da6-a7ce-f56ea918617e","text":"Cos we were just kids when we fell in love","position":8,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":53977,"audio_start_ms":50348,"audio_clip_object_key":null},{"id":"0746ce59-d402-4781-a040-7c5c187407b1","text":"I did, and it''s fantastically beautiful.","position":46,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":279377,"audio_start_ms":276177,"audio_clip_object_key":null},{"id":"0788780b-1117-4840-8a64-27a5bd4124f2","text":"- Freakin'' lads.","position":1,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":3315,"audio_start_ms":2830,"audio_clip_object_key":null},{"id":"088dcd78-a07f-4d1f-b888-73e073017b36","text":"So again, unless when you''re a teenager, you have parents who want to drive you around everywhere.","position":41,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":250837,"audio_start_ms":242517,"audio_clip_object_key":null},{"id":"098d12be-0a89-4023-96ae-cbd075b90eca","text":"Now, Georgie, what is it about the countryside that you don''t like?","position":30,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":178948,"audio_start_ms":174868,"audio_clip_object_key":null},{"id":"09e799a2-07e4-419f-aac9-c96ecd383bd8","text":"I''m reaching for the love that seems so far","position":52,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":187922,"audio_start_ms":184027,"audio_clip_object_key":null},{"id":"0b419818-8bd6-4f53-85b5-f96cc3c508a6","text":"I''m very well, thank you, Neil.","position":1,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":3360,"audio_start_ms":1600,"audio_clip_object_key":null},{"id":"0ca1c86f-d51f-4d70-bdad-8a812739ed96","text":"It does slow you down a bit, but we don''t need to have a fast pace when we''re in the countryside.","position":29,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":174028,"audio_start_ms":168708,"audio_clip_object_key":null},{"id":"0e064d0b-ab94-41fe-babd-28fd312d2756","text":"And oh, my love","position":19,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":56598,"audio_start_ms":54265,"audio_clip_object_key":null},{"id":"113c22b3-de0d-4c0d-a27d-553dc6bd3cd1","text":"When you said you looked a mess","position":19,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":101643,"audio_start_ms":99248,"audio_clip_object_key":null},{"id":"1404edee-e458-4059-b029-730bd3597ad8","text":"I''m going.","position":10,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":18860,"audio_start_ms":18374,"audio_clip_object_key":null},{"id":"14e5475a-c546-41ac-a6eb-3dbe45c06d6d","text":"Well, the countryside, like you said, is very relaxing.","position":17,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":89860,"audio_start_ms":85780,"audio_clip_object_key":null},{"id":"151076dc-5d7f-4a93-b98d-b700760a61aa","text":"To find a place I love the most","position":27,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":85688,"audio_start_ms":83620,"audio_clip_object_key":null},{"id":"15becc2d-570d-417e-8add-1aaa01c8c89d","text":"Oh, I never knew you were that someone waiting for me","position":7,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":48945,"audio_start_ms":43179,"audio_clip_object_key":null},{"id":"16ed37ca-4ded-4c2c-88ad-cc2bbe915d8c","text":"I''m OK.","position":6,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":11840,"audio_start_ms":11360,"audio_clip_object_key":null},{"id":"170649d1-059f-4185-a70a-cf4d1167baa3","text":"So that''s not very fun.","position":33,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":200948,"audio_start_ms":199988,"audio_clip_object_key":null},{"id":"180a472d-6388-4048-9eb1-be41ad9cbd5f","text":"The days we had, the songs we sang together","position":17,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":51693,"audio_start_ms":47644,"audio_clip_object_key":null},{"id":"18753a4c-3c7b-4ba4-9b59-33513f963d8f","text":"We also heard scenery and scenery is what you can see in a place and in the countryside the scenery is often beautiful.","position":66,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":417305,"audio_start_ms":410025,"audio_clip_object_key":null},{"id":"196f0bb5-e8a0-4983-905b-7f8b3f3dd045","text":"Wow.","position":26,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":163428,"audio_start_ms":162948,"audio_clip_object_key":null},{"id":"19894e10-0e21-4c04-8d21-e387df1ef279","text":"Dancing in the dark","position":46,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":229108,"audio_start_ms":227561,"audio_clip_object_key":null},{"id":"1a07ab7d-f8eb-4091-b6b1-eef2f62b3a5f","text":"Yeah, probably.","position":51,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":303037,"audio_start_ms":301677,"audio_clip_object_key":null},{"id":"1b20c7b2-7560-4720-b37f-a12133ba9a15","text":"But you heard it","position":21,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":106872,"audio_start_ms":105560,"audio_clip_object_key":null},{"id":"1b6c3497-404d-4484-9433-ea3c04ae0926","text":"My love","position":30,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":95683,"audio_start_ms":93740,"audio_clip_object_key":null},{"id":"1d14b759-ca08-4d5e-aeb2-714d088821e3","text":"A hole inside my heart","position":13,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":33087,"audio_start_ms":31174,"audio_clip_object_key":null},{"id":"20553fcd-31a2-4c12-907c-47f8eb5fe725","text":"It can be quite stressful though because the roads are one way and on either side of the road you have these big hedges so you can''t really see around the corners and if a car is coming towards you it''s not good.","position":56,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":361565,"audio_start_ms":345685,"audio_clip_object_key":null},{"id":"20ebed39-a840-44f3-8e6e-d69f639f73c3","text":"An empty street, an empty house","position":12,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":30551,"audio_start_ms":27642,"audio_clip_object_key":null},{"id":"21e064d0-d15b-4203-bff6-e9d8b4ad0cc2","text":"To find a place I love the most","position":45,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":156157,"audio_start_ms":153721,"audio_clip_object_key":null},{"id":"2212d89b-d27d-493d-93a0-40cd211e05f0","text":"We''ve also heard the adjective lush which describes a green area full of healthy plants and trees.","position":64,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":403385,"audio_start_ms":396745,"audio_clip_object_key":null},{"id":"23e65e7f-122c-42e5-b75f-b91fe05502b4","text":"Where the skies are blue","position":64,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":225636,"audio_start_ms":223690,"audio_clip_object_key":null},{"id":"291f7c53-473c-4a4c-a240-fc22791d686c","text":"- Forget this, we could go walking.","position":9,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":16986,"audio_start_ms":15640,"audio_clip_object_key":null},{"id":"2a01b204-1c6a-40ce-bcaf-151e295afe38","text":"(\"My Love\")","position":11,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":22766,"audio_start_ms":20616,"audio_clip_object_key":null},{"id":"2a78c7e0-62e3-4f0e-8b6c-6ee4165b0da8","text":"Yes, and wildlife is animals which live in natural environments, for example, badgers and birds.","position":63,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":396105,"audio_start_ms":389945,"audio_clip_object_key":null},{"id":"2b1d04d5-b819-429c-ade5-373252817735","text":"And you can go hiking, and you can see fantastic scenery.","position":48,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":294357,"audio_start_ms":288837,"audio_clip_object_key":null},{"id":"2cda47a4-310c-454b-b50c-50b51ec9738b","text":"So a remote place is somewhere that''s far away from towns and cities.","position":38,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":232817,"audio_start_ms":228417,"audio_clip_object_key":null},{"id":"2ce32be9-5e63-47b3-b355-a0120ab0d374","text":"To tell you from the heart","position":50,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":171895,"audio_start_ms":169466,"audio_clip_object_key":null},{"id":"2e56e52f-f69d-4281-8915-e1273807154d","text":"OK, well that is it for this episode of Real Easy English but don''t forget to sign up to our email newsletter.","position":67,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":424505,"audio_start_ms":417865,"audio_clip_object_key":null},{"id":"2fb6af34-5390-48ef-b477-d7afaa2292e2","text":"Listening to our favourite song","position":40,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":195134,"audio_start_ms":193150,"audio_clip_object_key":null},{"id":"309888cd-bcc9-4b23-85f6-a2329f29c0ae","text":"My love","position":61,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":217475,"audio_start_ms":217212,"audio_clip_object_key":null},{"id":"370c6e5c-fa7c-4de0-9884-44adc9d14efc","text":"No, they live in a small town, but you can say I live in the countryside if you live in a small town.","position":15,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":81420,"audio_start_ms":74460,"audio_clip_object_key":null},{"id":"3ae10539-b476-43aa-8f1c-d968e77b80b4","text":"I found a love","position":1,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":22462,"audio_start_ms":21378,"audio_clip_object_key":null},{"id":"3cf84f69-b82b-42e3-a017-af44c4160286","text":"Where the skies are blue","position":42,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":145257,"audio_start_ms":143609,"audio_clip_object_key":null},{"id":"3f20bd22-c646-44bb-b23d-1c52a127eab4","text":"- Oh my God!","position":3,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":7813,"audio_start_ms":7106,"audio_clip_object_key":null},{"id":"40012d0d-b060-455b-a90c-3ac1400d7e81","text":"I wonder how, I wonder why","position":15,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":42678,"audio_start_ms":40970,"audio_clip_object_key":null},{"id":"440f3347-1430-4d41-bd48-60cb0fc8d7bf","text":"Beautiful and sweet","position":6,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":42232,"audio_start_ms":40146,"audio_clip_object_key":null},{"id":"4424341e-f61b-423d-b213-520e85e8a653","text":"Barefoot on the grass","position":39,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":193130,"audio_start_ms":190803,"audio_clip_object_key":null},{"id":"44bd23b3-e2d5-4c44-9fb1-431137a2689b","text":"And hope my dreams will take me there","position":54,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":196889,"audio_start_ms":193955,"audio_clip_object_key":null},{"id":"458b726d-6bee-4dd0-af07-772e7154f619","text":"But people need to know they can get a worksheet and a transcript from our website, bbclearningenglish.com.","position":9,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":28560,"audio_start_ms":21120,"audio_clip_object_key":null},{"id":"4615dfdc-a27c-4aa1-baec-cc99c0bbcf69","text":"With you between my arms","position":38,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":186942,"audio_start_ms":185415,"audio_clip_object_key":null},{"id":"4866051b-8aa9-43e0-ae53-f587281bce6b","text":"Fighting against all odds","position":31,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":154240,"audio_start_ms":152611,"audio_clip_object_key":null},{"id":"499e30e4-0df7-40f7-b714-e30a63afcb11","text":"Reaching for the love that seems so far","position":39,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":134451,"audio_start_ms":131124,"audio_clip_object_key":null},{"id":"4ea9688e-08cb-4d28-8a34-ebb478d303b9","text":"Where the fields are green","position":46,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":158650,"audio_start_ms":156942,"audio_clip_object_key":null},{"id":"4eb7c5e9-f867-435e-8ef4-8098d0df587d","text":"To hold you in my arms","position":48,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":164547,"audio_start_ms":162804,"audio_clip_object_key":null},{"id":"4fd0078d-1477-4f39-8344-504017b9d6b5","text":"You''re all I''m thinking of","position":51,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":175605,"audio_start_ms":172818,"audio_clip_object_key":null},{"id":"50c8847d-75b6-4680-9e54-aec7f06eb7fb","text":"Goodbye.","position":70,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":432025,"audio_start_ms":431465,"audio_clip_object_key":null},{"id":"527b8074-c1b3-4bde-ae06-dd3d19062a15","text":"It can be very difficult to find things to do or exciting things to do.","position":39,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":237687,"audio_start_ms":233527,"audio_clip_object_key":null},{"id":"53209245-0d55-4700-9c57-4cafedf3bd70","text":"To see you once again, my love","position":25,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":79770,"audio_start_ms":76053,"audio_clip_object_key":null},{"id":"541dc2df-eee6-49a6-ab71-b5290f03fb95","text":"so I''m feeling very relaxed.","position":3,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":8240,"audio_start_ms":6320,"audio_clip_object_key":null},{"id":"54cbb7d0-df7c-446d-ac0d-853e5dd5b5a7","text":"You must.","position":28,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":168628,"audio_start_ms":167988,"audio_clip_object_key":null},{"id":"568107d1-09bc-45b4-8267-8c6ffc6662ba","text":"I had a lot of fresh air.","position":4,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":9680,"audio_start_ms":8240,"audio_clip_object_key":null},{"id":"57c3e908-70db-4aa9-96cb-179693d504b8","text":"I wonder where they are","position":35,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":116597,"audio_start_ms":114284,"audio_clip_object_key":null},{"id":"5994bb56-c1ca-4eb1-9f7c-6f3df97ce31b","text":"Now I know I have met an angel in person","position":51,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":251981,"audio_start_ms":245698,"audio_clip_object_key":null},{"id":"5a8b46f8-81fd-4e0d-bc60-fa57ce3da5e6","text":"For me","position":2,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":25751,"audio_start_ms":24444,"audio_clip_object_key":null},{"id":"5dd68372-945b-4f2d-85ad-d29bfaaabdc3","text":"But in England, the Lake District is fantastic.","position":53,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":312517,"audio_start_ms":310037,"audio_clip_object_key":null},{"id":"5e8d4927-0277-411d-9564-fff47c7c4c0c","text":"Where the skies are blue","position":55,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":198761,"audio_start_ms":196949,"audio_clip_object_key":null},{"id":"5fe1a2a0-5791-427a-a6a7-bb0f017d9c98","text":"We also heard the adjective remote which describes a place that''s far away from towns and cities.","position":65,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":409545,"audio_start_ms":403625,"audio_clip_object_key":null},{"id":"615af94c-f1bd-4fc7-8fc1-cb38d09bdb62","text":"To see you once again, my love","position":56,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":202193,"audio_start_ms":199444,"audio_clip_object_key":null},{"id":"61d7f87e-9921-4054-90f7-ac62e646e231","text":"There are mountains and lakes, and it''s very lush green because of all the rain.","position":47,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":287337,"audio_start_ms":281097,"audio_clip_object_key":null},{"id":"66435ef9-ddba-4616-8309-a56532bd33b4","text":"Now, Neil, I know that you have recently been on a little trip, haven''t you?","position":44,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":272897,"audio_start_ms":268097,"audio_clip_object_key":null},{"id":"6882c0c9-1a4c-4497-aa4d-c9172820e5da","text":"That''s the same old story. - You serious?","position":6,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":12116,"audio_start_ms":10740,"audio_clip_object_key":null},{"id":"6b086b1d-6abf-4d8c-a248-d3085fadf371","text":"- What are you talking about again?","position":4,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":9060,"audio_start_ms":7913,"audio_clip_object_key":null},{"id":"6b546481-a55b-4145-b24f-ec4e9010a8a0","text":"Darling, you look perfect tonight","position":43,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":211424,"audio_start_ms":207554,"audio_clip_object_key":null},{"id":"6bf1b3b6-09f8-4c4a-a9fc-95b37c4b3f27","text":"To see you once again","position":60,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":214419,"audio_start_ms":212792,"audio_clip_object_key":null},{"id":"6c1a7f5d-af17-4708-8ab5-4e9b27d1d5ba","text":"To see you once again","position":65,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":228509,"audio_start_ms":226117,"audio_clip_object_key":null},{"id":"6d42162d-f879-47dd-a557-48849ab973d8","text":"And I think it''s kind of boring.","position":36,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":210468,"audio_start_ms":208548,"audio_clip_object_key":null},{"id":"6e22a28d-25a8-432b-b334-dcdbe3a6655f","text":"To find the place I love the most","position":67,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":236542,"audio_start_ms":233608,"audio_clip_object_key":null},{"id":"6f60a092-d838-4a43-aa5b-802c547b7b85","text":"I will not give you up this time","position":10,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":64864,"audio_start_ms":59298,"audio_clip_object_key":null},{"id":"6fa898be-8fd7-43e2-b26d-8ee2bdb7a580","text":"Darling, just kiss me slow","position":11,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":69117,"audio_start_ms":66087,"audio_clip_object_key":null},{"id":"72ac2c26-53b2-4703-9757-d10b54468601","text":"We are still kids, but we''re so in love","position":30,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":152490,"audio_start_ms":148894,"audio_clip_object_key":null},{"id":"76241242-07d8-487a-86cc-8a824c608b63","text":"The days we had, the songs we sang together, oh, yeah","position":36,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":122983,"audio_start_ms":117784,"audio_clip_object_key":null},{"id":"763ed699-8708-4ceb-8572-55a5efee8e7e","text":"To see you once again","position":47,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":161159,"audio_start_ms":159413,"audio_clip_object_key":null},{"id":"77bb2ed6-b982-4d3b-b87c-81acec17bda6","text":"- Lads, if if I have to fly this plane myself,","position":7,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":13910,"audio_start_ms":12460,"audio_clip_object_key":null},{"id":"7841e181-564b-47e5-b2ae-e9715d065975","text":"Well, I found a woman","position":23,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":121269,"audio_start_ms":119584,"audio_clip_object_key":null},{"id":"78e06633-457c-45b6-a2b7-264c3ce5a033","text":"I must come on a walk with you in the countryside.","position":27,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":167588,"audio_start_ms":163988,"audio_clip_object_key":null},{"id":"7a0bfdf2-779b-4429-9cdf-0f2f304cd827","text":"If you start liking music and you want to go to concerts and do things which are usually in the city then living in the countryside can be a bit dull Yes, particularly if you live in a place that''s very remote.","position":37,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":228407,"audio_start_ms":211768,"audio_clip_object_key":null},{"id":"7d22a667-bb2e-42b5-96a4-89aef354ee8a","text":"Would you say it''s your favourite countryside area in the UK?","position":50,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":300877,"audio_start_ms":296397,"audio_clip_object_key":null},{"id":"7e0c807b-1844-4b93-b918-ddfd4384bdc6","text":"So I can...","position":23,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":150348,"audio_start_ms":148908,"audio_clip_object_key":null},{"id":"80078498-a197-4e52-b3a2-d5fa1bedfbc0","text":"Now, you also like leaves, don''t you?","position":21,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":137528,"audio_start_ms":135368,"audio_clip_object_key":null},{"id":"80a6a51f-b459-493d-a4bf-1f5c6571af14","text":"My love","position":70,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":245588,"audio_start_ms":244184,"audio_clip_object_key":null},{"id":"80fe853b-6a66-44cd-9758-23687a9985ed","text":"(Darling, oh)","position":44,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":218701,"audio_start_ms":216846,"audio_clip_object_key":null},{"id":"86a2522a-5145-47d1-ae96-e78e162c7a7a","text":"Dreams will take me there","position":63,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":223167,"audio_start_ms":221157,"audio_clip_object_key":null},{"id":"8925264d-8c0b-4dc3-82d8-a8d5ae87c802","text":"Where the fields are green","position":59,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":211082,"audio_start_ms":210217,"audio_clip_object_key":null},{"id":"895e853c-da24-4441-acc6-a140fd9b3237","text":"I don''t deserve this","position":53,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":256517,"audio_start_ms":255776,"audio_clip_object_key":null},{"id":"8a67cf4e-d682-4841-b7ad-90df19b72268","text":"And hope my dreams will take me there","position":23,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":73084,"audio_start_ms":70888,"audio_clip_object_key":null},{"id":"8dacb298-330b-4e53-80e8-1a26e405a5de","text":"I wonder how, I wonder why","position":34,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":113802,"audio_start_ms":111170,"audio_clip_object_key":null},{"id":"8e048b6d-cbb2-4ba5-97a3-ed1c7b65318f","text":"It''s a great place.","position":49,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":296117,"audio_start_ms":295317,"audio_clip_object_key":null},{"id":"8f09e070-45c2-488c-9fb3-741069bf4dc5","text":"- Please tell me you''re joking.","position":5,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":10011,"audio_start_ms":9100,"audio_clip_object_key":null},{"id":"911df686-cfc4-4086-bc69-2162256a9118","text":"now then to recap the vocabulary that we''ve used in this episode, starting with countryside.","position":61,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":379385,"audio_start_ms":373625,"audio_clip_object_key":null},{"id":"914afced-3a34-43e2-8b1e-73b04520c516","text":"I have faith in what I see","position":50,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":243707,"audio_start_ms":242158,"audio_clip_object_key":null},{"id":"91a22dbd-e39d-4c10-bc29-447691bb01ca","text":"Overseas, from coast to coast","position":57,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":205300,"audio_start_ms":203737,"audio_clip_object_key":null},{"id":"92165f5c-0770-408b-92a9-bf5bcc2fb713","text":"When I turned 17, which is the age that you can start driving in the UK, my parents pushed me to take lessons immediately because they were very tired of driving me around everywhere.","position":43,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":266957,"audio_start_ms":253327,"audio_clip_object_key":null},{"id":"930f7841-2fa3-4c1e-b552-b48e98449e56","text":"To see you once again, my love","position":43,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":149389,"audio_start_ms":146081,"audio_clip_object_key":null},{"id":"94a744a4-5de2-4636-b665-979178d52ba8","text":"To promise you my love","position":49,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":168220,"audio_start_ms":166130,"audio_clip_object_key":null},{"id":"95bab6dc-f777-4120-a059-fdd9876ea548","text":"So, I say a little prayer","position":22,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":69480,"audio_start_ms":66909,"audio_clip_object_key":null},{"id":"97b1b27b-69d3-4a2b-b46d-84f02f54def1","text":"You went to the Lake District in the north of England.","position":45,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":275837,"audio_start_ms":273037,"audio_clip_object_key":null},{"id":"980ef226-4367-4b56-aab5-26e67093484d","text":"To see you once again","position":69,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":243120,"audio_start_ms":239483,"audio_clip_object_key":null},{"id":"9830a9c5-529a-46e9-a810-8298eebd0c08","text":"Overseas, from coast to coast","position":44,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":153058,"audio_start_ms":150532,"audio_clip_object_key":null},{"id":"9848c14e-88c1-466d-a050-4a5c22bbeca8","text":"And in your eyes, you''re holding mine","position":13,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":79412,"audio_start_ms":74438,"audio_clip_object_key":null},{"id":"9a7ec5cc-8c1c-457f-961a-87a2777e2fd2","text":"It doesn''t mean they live in a field.","position":14,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":73880,"audio_start_ms":71800,"audio_clip_object_key":null},{"id":"9c604e6b-bbfe-4150-8e98-5c92dda601d2","text":"I mean, parts of Scotland are really spectacular, with even bigger mountains.","position":52,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":309357,"audio_start_ms":303117,"audio_clip_object_key":null},{"id":"9d19c673-254e-4b4d-ae49-083f37532ea9","text":"[TRAIN RATTLES IN DISTANCE]","position":0,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":3088,"audio_start_ms":1023,"audio_clip_object_key":null},{"id":"9da287a7-a7ac-49da-b072-f1a1e06ce679","text":"That''s very true, actually.","position":42,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":253267,"audio_start_ms":251027,"audio_clip_object_key":null},{"id":"9df45f0e-edef-4bd9-9fcd-931d577517a9","text":"To find the place I love the most","position":58,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":210137,"audio_start_ms":206943,"audio_clip_object_key":null},{"id":"a0e07979-f640-4b78-b202-05d55ab12d4b","text":"Reaching for the love that seems so far","position":21,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":63981,"audio_start_ms":61175,"audio_clip_object_key":null},{"id":"a110b747-6738-49c1-a52a-ea334105889e","text":"And oh, my love","position":37,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":125715,"audio_start_ms":124111,"audio_clip_object_key":null},{"id":"a24352ff-f85a-4b8d-b169-674a97ae31ab","text":"With you between my arms","position":47,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":232405,"audio_start_ms":231101,"audio_clip_object_key":null},{"id":"a32f1952-2b22-42ca-8a58-2b68ff1bf2e1","text":"I''ve just spent the weekend in the countryside,","position":2,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":6000,"audio_start_ms":3360,"audio_clip_object_key":null},{"id":"a54ed246-fb04-4221-bd1d-e3e04e8079b1","text":"Neil, what do you like about the British countryside?","position":16,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":85340,"audio_start_ms":81900,"audio_clip_object_key":null},{"id":"a565afde-2099-41d7-a81b-b27086358059","text":"I''m laughing with my friends","position":32,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":103540,"audio_start_ms":101005,"audio_clip_object_key":null},{"id":"a5f85862-2d99-42ad-82dd-f4ffc4053c6c","text":"How are you doing?","position":5,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":10960,"audio_start_ms":10160,"audio_clip_object_key":null},{"id":"a700c042-2b3e-4fcc-8e3d-e462b5bd98d6","text":"I whispered underneath my breath","position":20,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":105439,"audio_start_ms":102828,"audio_clip_object_key":null},{"id":"a7185c56-e61e-40b1-b525-c429c71fe5ac","text":"To see you once again","position":29,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":90826,"audio_start_ms":89419,"audio_clip_object_key":null},{"id":"aa73d793-ce76-4b06-8c48-1070c0f89512","text":"Listening to our favourite song","position":18,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":98181,"audio_start_ms":95867,"audio_clip_object_key":null},{"id":"aab6f9d7-3b46-450d-8cf6-e922a2a872d3","text":"What I really like about the British countryside in particular is that it very green and lush That because we get a lot of rain but I also really like being close to the wildlife as well I once came very close to a baby badger which is an animal that you can find in the well it''s actually not very easy to find in the UK.","position":19,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":129448,"audio_start_ms":102680,"audio_clip_object_key":null},{"id":"ad39b9db-e59c-4c6f-9bae-da46a7b5dc47","text":"Barefoot on the grass","position":17,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":93193,"audio_start_ms":91122,"audio_clip_object_key":null},{"id":"ae8d75d9-ef99-4fb4-8ccb-740df1ccc408","text":"Dancing in the dark","position":15,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":86176,"audio_start_ms":83773,"audio_clip_object_key":null},{"id":"b10d8072-e128-4a50-b37f-8c775ecaae1d","text":"The last flight''s just been canceled.","position":2,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":5045,"audio_start_ms":3840,"audio_clip_object_key":null},{"id":"b3b5ec44-b6ef-4140-8bfe-84c587a575d4","text":"A reason I like the countryside is because it''s green, because we get lots of rain, but the downside of all the rain is that sometimes the countryside can be very muddy.","position":31,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":191068,"audio_start_ms":180788,"audio_clip_object_key":null},{"id":"b476411b-4f7b-4c56-9627-57157f21b328","text":"Darling, just hold my hand","position":33,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":167751,"audio_start_ms":164923,"audio_clip_object_key":null},{"id":"b5c6642d-799a-43cd-9f08-74e0ec3230f7","text":"Not knowing what it was","position":9,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":57916,"audio_start_ms":55363,"audio_clip_object_key":null},{"id":"b7106304-0730-479e-98f7-ae33a474260c","text":"And hope my dreams will take me there","position":41,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":142985,"audio_start_ms":140871,"audio_clip_object_key":null},{"id":"b90d8745-0535-4875-b84b-cb37c6f7cddc","text":"Overseas, from coast to coast","position":66,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":232866,"audio_start_ms":230419,"audio_clip_object_key":null},{"id":"bb4c3a87-9b1a-4eb6-8e42-ad0aca28260a","text":"Oh, yeah","position":18,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":53279,"audio_start_ms":52495,"audio_clip_object_key":null},{"id":"bc43cd11-7419-471b-9178-4c130e78d815","text":"We''ll be back next week with another episode, but bye for now.","position":69,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":431225,"audio_start_ms":428425,"audio_clip_object_key":null},{"id":"bd9a1c95-d114-4948-b07b-5eae32a10f9d","text":"I wonder where they are","position":16,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":46598,"audio_start_ms":44990,"audio_clip_object_key":null},{"id":"bf1a664f-75df-41ff-91f6-44ffbdab5426","text":"You look perfect tonight","position":54,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":264095,"audio_start_ms":259841,"audio_clip_object_key":null},{"id":"c0a8e828-7c20-418f-be31-759e2416a81a","text":"And follow my lead","position":4,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":33584,"audio_start_ms":31796,"audio_clip_object_key":null},{"id":"c24b9a49-939a-4e96-bbfa-f0b677226c6c","text":"So, I say a little prayer","position":40,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":139645,"audio_start_ms":136916,"audio_clip_object_key":null},{"id":"c611006f-73bb-4d02-9d93-57497103796e","text":"So this means that the ground is very wet and sludgy, and it can make your shoes very dirty.","position":32,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":199468,"audio_start_ms":191568,"audio_clip_object_key":null},{"id":"c6c1064a-097d-4ef3-97ed-d86fcf73d7bd","text":"I''m holding on forever","position":20,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":59450,"audio_start_ms":57905,"audio_clip_object_key":null},{"id":"c6e3b779-7521-47ee-a5f1-c2f38a4f26c3","text":"Yeah.","position":59,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":365845,"audio_start_ms":365365,"audio_clip_object_key":null},{"id":"c7f7b199-5d8a-40d2-be0b-3f88550ab5b6","text":"To carry more than just my secrets","position":28,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":141541,"audio_start_ms":138726,"audio_clip_object_key":null},{"id":"c7ff6a96-6f86-4aec-a4fe-59d3391ca77e","text":"sometimes I go for a walk and I put the pictures up next to the trees and I can identify which ones I''m seeing.","position":24,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":160348,"audio_start_ms":151148,"audio_clip_object_key":null},{"id":"c95d6d5e-bb8c-4f24-95fb-49dc288a1485","text":"She shares my dreams","position":25,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":127213,"audio_start_ms":125646,"audio_clip_object_key":null},{"id":"ca36f8ae-b77b-4fc5-a1e4-01e8321c1509","text":"(plane roaring)","position":0,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":923,"audio_start_ms":141,"audio_clip_object_key":null},{"id":"cbd55c3b-a3e5-4430-8911-0cf73ee8c65b","text":"I really hate that.","position":60,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":373565,"audio_start_ms":366365,"audio_clip_object_key":null},{"id":"cdc64d21-5d6e-4dfa-a5d2-28c6b4a4d625","text":"No, it''s a nightmare.","position":57,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":362905,"audio_start_ms":361705,"audio_clip_object_key":null},{"id":"ce1b88e4-d349-485e-83ee-0115d0ceaff7","text":"Your heart is all I own","position":12,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":72391,"audio_start_ms":70443,"audio_clip_object_key":null},{"id":"cea0ef55-02b0-49c4-b885-6f2a2b1be477","text":"Well, that''s a good question, actually, because the countryside is the green area outside of the city with hills and grass and fields, but we also talk about villages and small towns outside of the city as the countryside.","position":12,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":67960,"audio_start_ms":48560,"audio_clip_object_key":null},{"id":"cf0ab53a-c6d6-439e-993d-287eb03761b1","text":"To carry love, to carry children of our own","position":29,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":148171,"audio_start_ms":142964,"audio_clip_object_key":null},{"id":"cf3f5227-2846-42d5-a42a-ee157b3f9911","text":"I don''t deserve this","position":42,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":205123,"audio_start_ms":202909,"audio_clip_object_key":null},{"id":"cf5a1d61-8e16-4d16-93d6-0004bd313dd8","text":"You might have to reverse for ages.","position":58,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":365085,"audio_start_ms":363165,"audio_clip_object_key":null},{"id":"cf6c8f49-ada1-4f48-9b2f-5cbf4122d65f","text":"Baby, I''m...","position":45,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":224955,"audio_start_ms":223652,"audio_clip_object_key":null},{"id":"cfb92892-02cf-43c0-ab00-c0f2d006753e","text":"Now, the countryside is the area outside of the cities where not many people live and there''s lots of nature and wildlife.","position":62,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":389625,"audio_start_ms":379625,"audio_clip_object_key":null},{"id":"d29d98ce-4afb-4634-8f3c-d21963c928b3","text":"You can get weekly tips and updates from your favourite presenters.","position":68,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":427945,"audio_start_ms":424585,"audio_clip_object_key":null},{"id":"d38ce380-bca1-474b-9681-15483e200ac0","text":"Yes, I have a little booklet which has pictures of leaves so that I can identify different trees.","position":22,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":148908,"audio_start_ms":139048,"audio_clip_object_key":null},{"id":"d4302bb0-f48e-4987-93c4-cab1b28c3eaa","text":"Yeah, it''s difficult to get around as well unless you drive.","position":40,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":242197,"audio_start_ms":238037,"audio_clip_object_key":null},{"id":"d43cfe5e-83e3-4345-8e56-9104a3fd114c","text":"Barefoot on the grass","position":48,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":238655,"audio_start_ms":236308,"audio_clip_object_key":null},{"id":"d4598e35-3880-47a4-be7f-9651ec1b03c5","text":"Well, I found a girl","position":5,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":37956,"audio_start_ms":35150,"audio_clip_object_key":null},{"id":"d599a259-31b3-4814-ac48-6292f33ae1a4","text":"I''m going home.","position":8,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":15540,"audio_start_ms":14151,"audio_clip_object_key":null},{"id":"d89c7aff-3988-4426-92b0-7fd4f3c2fd6b","text":"Darling, just dive right in","position":3,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":30905,"audio_start_ms":28801,"audio_clip_object_key":null},{"id":"d953ef1a-ddb7-425f-a8f3-0072c6f37045","text":"With you between my arms","position":16,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":90715,"audio_start_ms":88183,"audio_clip_object_key":null},{"id":"dbcbc0e0-9b81-41f7-bdbd-bbed25aa5563","text":"I''m holding on forever","position":38,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":130178,"audio_start_ms":127841,"audio_clip_object_key":null},{"id":"dc5892ac-4d50-442f-a77b-a52c3316881d","text":"So, we have talked about the countryside on this podcast in Real Easy English before, but we''ve had some people commenting, asking what actually is the countryside.","position":10,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":45600,"audio_start_ms":34800,"audio_clip_object_key":null},{"id":"df1e4eec-8ed5-4eb3-9e14-52838b19aa73","text":"Where the fields are green","position":68,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":238517,"audio_start_ms":236964,"audio_clip_object_key":null},{"id":"e2058a70-9246-4516-b7ec-db6287b7ac4c","text":"It''s black and white and I saw it during Covid and it came very close to us.","position":20,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":134928,"audio_start_ms":129848,"audio_clip_object_key":null},{"id":"e2168f92-dd37-4c55-9b3b-3874d6ee624b","text":"Baby, I''m...","position":14,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":82088,"audio_start_ms":80922,"audio_clip_object_key":null},{"id":"e48c7fa2-fa86-460b-a050-eefe8d91d44d","text":"Overseas, from coast to coast","position":26,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":82998,"audio_start_ms":80392,"audio_clip_object_key":null},{"id":"e6c2e4bb-2063-4816-b839-1f29d58ce220","text":"There''s not a lot of busy traffic.","position":55,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":345685,"audio_start_ms":343425,"audio_clip_object_key":null},{"id":"e7554fed-b300-48d7-a324-2837cc09c55d","text":"But I can''t stop to keep myself from thinking, oh no","position":33,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":109503,"audio_start_ms":104244,"audio_clip_object_key":null},{"id":"e824828c-f900-4681-b798-57eb5313918f","text":"Stronger than anyone I know","position":24,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":124640,"audio_start_ms":123455,"audio_clip_object_key":null},{"id":"e9245ffc-f16b-40c3-8a27-7aecad5a3910","text":"I hope that someday I''ll share her home, oh","position":26,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":133062,"audio_start_ms":128537,"audio_clip_object_key":null},{"id":"eccc3708-7169-4152-b404-75adaefc821e","text":"I know we''ll be alright this time","position":32,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":162139,"audio_start_ms":156854,"audio_clip_object_key":null},{"id":"ee602a36-aa1f-4eb3-bbe1-eff8770ed719","text":"and that''s what we''re talking about in this episode of Real Easy English.","position":8,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":20960,"audio_start_ms":17040,"audio_clip_object_key":null},{"id":"ee750457-3f9d-40be-8562-8e2e316e9878","text":"And I''ve learnt a lot, actually.","position":25,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":162268,"audio_start_ms":160428,"audio_clip_object_key":null},{"id":"ee7728d2-e7f8-4d8a-bca4-355229f95048","text":"It''s not busy, and there''s fresh air and you can walk in hills, fields, with great views very easily.","position":18,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":101460,"audio_start_ms":90660,"audio_clip_object_key":null},{"id":"ef765bef-dd57-4713-8988-d6b7ef958b76","text":"And in Wales, I recently went to the Pembrokeshire coast that in the west of Wales and there just stunning scenery there beaches coastal walks fantastic Yes I saw the photos of that trip It looked amazing My favourite countryside area is probably Cornwall and Devon the southwest of England Once you start driving down there, the roads are very small.","position":54,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":343265,"audio_start_ms":312757,"audio_clip_object_key":null},{"id":"efcfa53d-b0ea-47e9-abd1-e85b2eee9093","text":"Well, when I was a teenager, I lived in the countryside.","position":35,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":207348,"audio_start_ms":202388,"audio_clip_object_key":null},{"id":"f29741d4-1a64-4367-9c94-7161ebd7fcea","text":"So, Neil, maybe you can help us out.","position":11,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":48240,"audio_start_ms":45600,"audio_clip_object_key":null},{"id":"f2f7ef24-f31e-4613-8ca9-f4a494a54145","text":"I found a lover","position":27,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":136594,"audio_start_ms":134104,"audio_clip_object_key":null},{"id":"f3d792fe-a674-495b-a398-c3dc10a69fc9","text":"I see my future in your eyes","position":35,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":174588,"audio_start_ms":171564,"audio_clip_object_key":null},{"id":"f4244624-bdb1-48bc-9e13-c03709308293","text":"Darling, you look perfect tonight","position":22,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":111900,"audio_start_ms":109047,"audio_clip_object_key":null},{"id":"f4412ec6-a11c-4c25-9ce6-656f45d1cc70","text":"Say a little prayer, my sweet love","position":62,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":221037,"audio_start_ms":218040,"audio_clip_object_key":null},{"id":"f6116aca-bf1a-4dfe-97a3-c1bac1df99f5","text":"And she looks perfect","position":52,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":254591,"audio_start_ms":252101,"audio_clip_object_key":null},{"id":"f61b2a3a-5776-487f-8aff-a4501f8b7f96","text":"So you said, my parents live in the countryside.","position":13,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":71400,"audio_start_ms":68200,"audio_clip_object_key":null},{"id":"f768aed3-3339-4568-bcbc-c5eeccbf7950","text":"Baby, I''m...","position":36,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":178534,"audio_start_ms":178052,"audio_clip_object_key":null},{"id":"f8b6ad4f-6398-46f5-a332-added3ab8a79","text":"Dancing in the dark","position":37,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":185355,"audio_start_ms":183228,"audio_clip_object_key":null},{"id":"fe0a4cae-3c68-4354-b7d2-ef9c76457df5","text":"Hi Georgie, how are you?","position":0,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":1280,"audio_start_ms":240,"audio_clip_object_key":null},{"id":"ff0c8f82-f385-490a-a1f9-94b02ff74cff","text":"Be my girl, I''ll be your man","position":34,"lesson_id":"f980ebca-bda3-404b-bce2-cac12b3eece6","audio_end_ms":171444,"audio_start_ms":168072,"audio_clip_object_key":null},{"id":"ff40cc8e-6193-45f0-bdd8-c5684d658976","text":"I try to read, I go to work","position":31,"lesson_id":"cb5ccc06-ec68-440d-83a0-7acfffdc265e","audio_end_ms":100381,"audio_start_ms":98108,"audio_clip_object_key":null},{"id":"ff4eab86-9eba-4780-b9b4-72593300c87a","text":"What about you?","position":34,"lesson_id":"b42b20ce-1864-4111-9cc5-49da2bef34d3","audio_end_ms":201708,"audio_start_ms":201228,"audio_clip_object_key":null}]'::jsonb) snapshot
