null,"content_profile":{"key":"9d56e75f06d1545ee156256f495d91df11e7045ecd75fbb3d7a97321ad747b0e","cefr":"A2","manual":false,"contentType":"OTHER"},"source_start_ms":0,"timing_evidence":{"segments":[{"text":"(plane roaring)","end_ms":2790,"start_ms":443},{"text":"- Freakin'' lads.","end_ms":3840,"start_ms":2790},{"text":"The last flight''s just been canceled.","end_ms":5690,"start_ms":3840},{"text":"- Oh my God!","end_ms":7853,"start_ms":7020},{"text":"- What are you talking about again?","end_ms":9060,"start_ms":7853},{"text":"- Please tell me you''re joking.","end_ms":10740,"start_ms":9060},{"text":"That''s the same old story. - You serious?","end_ms":12420,"start_ms":10740},{"text":"- Lads, if if I have to fly this plane myself,","end_ms":13950,"start_ms":12420},{"text":"I''m going home.","end_ms":15600,"start_ms":13950},{"text":"- Forget this, we could go walking.","end_ms":17350,"start_ms":15600},{"text":"I''m going.","end_ms":20074,"start_ms":18510},{"text":"(\"My Love\")","end_ms":22407,"start_ms":20074},{"text":"An empty street, an empty house","end_ms":31053,"start_ms":28042},{"text":"A hole inside my heart","end_ms":34255,"start_ms":31053},{"text":"I''m all alone, the rooms are getting smaller","end_ms":39255,"start_ms":34255},{"text":"I wonder how, I wonder why","end_ms":44286,"start_ms":41128},{"text":"I wonder where they are","end_ms":47644,"start_ms":44286},{"text":"The days we had, the songs we sang together","end_ms":52495,"start_ms":47644},{"text":"Oh, yeah","end_ms":54164,"start_ms":52495},{"text":"And oh, my love","end_ms":57745,"start_ms":54164},{"text":"I''m holding on forever","end_ms":61115,"start_ms":57745},{"text":"Reaching for the love that seems so far","end_ms":66115,"start_ms":61115},{"text":"So, I say a little prayer","end_ms":70284,"start_ms":66980},{"text":"And hope my dreams will take me there","end_ms":73568,"start_ms":70284},{"text":"Where the skies are blue","end_ms":75671,"start_ms":73568},{"text":"To see you once again, my love","end_ms":80292,"start_ms":75671},{"text":"Overseas, from coast to coast","end_ms":83439,"start_ms":80292},{"text":"To find a place I love the most","end_ms":86773,"start_ms":83439},{"text":"Where the fields are green","end_ms":89057,"start_ms":86773},{"text":"To see you once again","end_ms":93680,"start_ms":89057},{"text":"My love","end_ms":97947,"start_ms":93680},{"text":"I try to read, I go to work","end_ms":100884,"start_ms":97947},{"text":"I''m laughing with my friends","end_ms":104144,"start_ms":100884},{"text":"But I can''t stop to keep myself from thinking, oh no","end_ms":109144,"start_ms":104144},{"text":"I wonder how, I wonder why","end_ms":114264,"start_ms":111067},{"text":"I wonder where they are","end_ms":117563,"start_ms":114264},{"text":"The days we had, the songs we sang together, oh, yeah","end_ms":122563,"start_ms":117563},{"text":"And oh, my love","end_ms":127720,"start_ms":124270},{"text":"I''m holding on forever","end_ms":131024,"start_ms":127720},{"text":"Reaching for the love that seems so far","end_ms":136024,"start_ms":131024},{"text":"So, I say a little prayer","end_ms":140227,"start_ms":136967},{"text":"And hope my dreams will take me there","end_ms":143508,"start_ms":140227},{"text":"Where the skies are blue","end_ms":145760,"start_ms":143508},{"text":"To see you once again, my love","end_ms":150372,"start_ms":145760},{"text":"Overseas, from coast to coast","end_ms":153459,"start_ms":150372},{"text":"To find a place I love the most","end_ms":156842,"start_ms":153459},{"text":"Where the fields are green","end_ms":158992,"start_ms":156842},{"text":"To see you once again","end_ms":162724,"start_ms":158992},{"text":"To hold you in my arms","end_ms":165949,"start_ms":162724},{"text":"To promise you my love","end_ms":169205,"start_ms":165949},{"text":"To tell you from the heart","end_ms":172417,"start_ms":169205},{"text":"You''re all I''m thinking of","end_ms":176167,"start_ms":172417},{"text":"I''m reaching for the love that seems so far","end_ms":189307,"start_ms":184326},{"text":"So, I say a little prayer","end_ms":193553,"start_ms":189307},{"text":"And hope my dreams will take me there","end_ms":196949,"start_ms":193553},{"text":"Where the skies are blue","end_ms":199043,"start_ms":196949},{"text":"To see you once again, my love","end_ms":203677,"start_ms":199043},{"text":"Overseas, from coast to coast","end_ms":206802,"start_ms":203677},{"text":"To find the place I love the most","end_ms":210217,"start_ms":206802},{"text":"Where the fields are green","end_ms":212450,"start_ms":210217},{"text":"To see you once again","end_ms":216990,"start_ms":212450},{"text":"My love","end_ms":217859,"start_ms":216990},{"text":"Say a little prayer, my sweet love","end_ms":221097,"start_ms":217859},{"text":"Dreams will take me there","end_ms":223690,"start_ms":221097},{"text":"Where the skies are blue","end_ms":226037,"start_ms":223690},{"text":"To see you once again","end_ms":230198,"start_ms":226037},{"text":"Overseas, from coast to coast","end_ms":233508,"start_ms":230198},{"text":"To find the place I love the most","end_ms":236904,"start_ms":233508},{"text":"Where the fields are green","end_ms":239222,"start_ms":236904},{"text":"To see you once again","end_ms":243703,"start_ms":239222},{"text":"My love","end_ms":245870,"start_ms":243703}],"transcriptSource":"YOUTUBE_EN_MANUAL"},"approved_revision":null,"semantic_revision":null,"generation_options":{"accent":"US","locale":"vi-VN","density":"AUTO","activities":["DICTATION","SHADOWING"],"annotations":["PROFILE","TRANSLATION","LEXICAL","GRAMMAR"],"grammarLimit":8,"vocabularyLimit":20,"pronunciationProvider":"LOCAL","pronunciationStrategy":"PREGENERATE"},"source_selected_at":"2026-11-23T03:53:13.2482+00:00","transcript_revision":1,"karaoke_reviewed_revision":null},{"document":[{"id":"fe0a4cae-3c68-4354-b7d2-ef9c76457df5","ipa":"hˈaɪ dʒˈɔːrdʒi hˈaʊ ɑːr juː","text":"Hi Georgie, how are you?","cloze":{"easy":[2],"text":"Hi Georgie, how are you?","medium":[1,2],"version":"